INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5a9b04d7-d0a3-4e6e-82a8-a1b1738ed399', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$11. óra: Összeszámlálási feladatok megoldása$q$, $q$Önálló feladatmegoldás rendszerezett felsorolással és faábrával.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "2cc6f24f-cd58-4014-9e02-b3c843a028c6", "text": "Hányféleképpen rakhatunk sorba 4 különböző könyvet a polcon? (4*3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "65cc8de6-e472-48ce-9cdd-ad79aed7c710", "text": "Hány 3 jegyű szám képezhető a 7, 8, 9 számjegyekből ha mindegyiket csak egyszer használhatjuk fel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "6a9b80e4-7f7c-47a2-97d4-a1acd6c55183", "text": "Az ágrajz utolsó szintjén lévő levelek száma megadja az összes lehetséges kimenetelt.", "type": "true-false", "options": [{"id": "e1ae697d-2432-4991-af0f-828f21597aa8", "text": "Igaz", "isCorrect": true}, {"id": "27bdae7e-9d51-4b1e-8f71-3b1dcd64ae7b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c9bbc7dd-096d-4670-bfb6-7df5a3a7134f", "text": "Melyik állítás igaz a valószínűségi kísérletekre?", "type": "multiple-choice", "options": [{"id": "b517a7aa-5974-4a1d-a5ce-e0103947dda9", "text": "A lehetséges esetek száma a kedvező és kedvezőtlen esetek összege", "isCorrect": true}, {"id": "878b7e4a-0107-451f-b72f-4d3e292981df", "text": "Mindig csak 1 eset lehetséges", "isCorrect": false}, {"id": "172614bf-2b1f-47e9-afec-12cbf7724a6c", "text": "Sohasem lehet kiszámolni az esetek számát", "isCorrect": false}, {"id": "e51c7b6e-276b-4871-87e9-8427d62bf695", "text": "Csak páros szám lehet az eredmény", "isCorrect": false}], "timeLimit": 15}, {"id": "574c8bad-85e5-49f1-8a36-c2f66db84ffa", "text": "Hányféle kétgombócos fagyit választhatunk 3-féle ízből, ha két különböző ízt kérünk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "73914b4f-fc37-47d0-843a-01375aeb95c5", "text": "Ha egy feldobott pénzérmét kétszer dobunk fel egymás után, a lehetséges kimenetelek száma 4.", "type": "true-false", "options": [{"id": "8f50d153-876e-455a-834c-154dbee1f346", "text": "Igaz (FF, FI, IF, II)", "isCorrect": true}, {"id": "5f2ad8df-4399-4dc6-92db-d9266b59b66a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9404c20e-7182-444a-b22a-a8899ea24448", "text": "Hány válaszlehetőség van egy 4 opciós feleletválasztós kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('94230532-944b-4c8b-8acd-4e841a37b4dc', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$12. óra: Számonkérés$q$, $q$Az egész számok műveleteiből és az összeszámlálásból tanultak számonkérése (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "d048f888-3b69-4d25-9738-4b24b306b416", "text": "1. Mennyi (-15) + (+20)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "5ceb2d4d-02f7-482e-9657-a03bb5772c1a", "text": "2. Mennyi (-6) * (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "f286e873-cd3c-445e-8249-1207334c24ee", "text": "3. Mennyi (-54) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "a42459a3-c601-469b-8edd-44fbc9e8b2dd", "text": "4. Melyik szám abszolút értéke nagyobb: |-30| vagy |+20|?", "type": "multiple-choice", "options": [{"id": "e0c90ed9-72d9-4548-9259-fe8f18bf2ebd", "text": "|-30|", "isCorrect": true}, {"id": "ebc6b7e3-92e3-4fef-b214-0f83d1c92eb9", "text": "|+20|", "isCorrect": false}, {"id": "c09aeafc-84fd-4786-9d2b-2c07bbff1b3b", "text": "Egyenlőek", "isCorrect": false}, {"id": "906a065c-b7a1-4d9a-a008-43803305c97a", "text": "Egyik sem", "isCorrect": false}], "timeLimit": 15}, {"id": "8f0abefc-07bd-4fa9-a4da-1588b988f29e", "text": "5. Mennyi (-3) * (-2) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}, {"id": "7d19b102-a28b-40d8-8a20-357e27214e0c", "text": "6. A negatív szám szorzása negatív számmal pozitív eredményt ad.", "type": "true-false", "options": [{"id": "9a4c6d91-aea2-4e1d-99a3-f2308c11b6bb", "text": "Igaz", "isCorrect": true}, {"id": "2636968c-a157-4a92-94a2-03d7e080d122", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cca24a05-e4bd-4191-a6ab-a9ad6eb31e53", "text": "7. Hány különböző sorrendben ülhet le 3 gyerek egy padra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "3ca5e7eb-8675-42ee-8f2b-cd505fea96a7", "text": "8. Mennyi (-40) : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "a188321f-d7f8-4060-a67b-ae9b5db56930", "text": "9. A nullának nincs ellentettje (vagy önmaga az ellentettje).", "type": "true-false", "options": [{"id": "e515e6d4-2fc2-4194-b303-151b84518a98", "text": "Igaz", "isCorrect": true}, {"id": "7561c42e-9f3e-4a57-9217-50bbf040183a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ff144020-fce5-44c1-afc8-d2d191bef1ed", "text": "10. Mennyi (-10) + (-20) - (-15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('37e07c0e-a1ec-4907-84b4-4e193fe196b4', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$13. óra: Osztó, többszörös$q$, $q$Osztó, többszörös fogalma, osztópárok meghatározása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "ddc321e8-6487-41bb-ae83-fb5b135dd3eb", "text": "Mit nevezünk egy 'a' természetes szám osztójának?", "type": "multiple-choice", "options": [{"id": "039f8f31-4f05-4383-8741-e19941865c8d", "text": "Azt a 'b' számot, amellyel 'a'-t elosztva a maradék 0", "isCorrect": true}, {"id": "37b7caa1-eee5-42cf-a49a-6971676a968b", "text": "Azt a számot, amit 'a'-hoz hozzáadunk", "isCorrect": false}, {"id": "ef52f475-bc69-480c-a2f6-48bcdfb35c5f", "text": "Azt a számot, ami nagyobb 'a'-nál", "isCorrect": false}, {"id": "bd61ead3-0b88-4a88-8388-235d12cdad3a", "text": "Minden páratlan számot", "isCorrect": false}], "timeLimit": 15}, {"id": "25cb53a8-39a1-47ab-84e3-6d34a7b85f08", "text": "Az 1 minden természetes számnak osztója.", "type": "true-false", "options": [{"id": "cca42ead-bd65-4f26-83a2-656ce81de2b1", "text": "Igaz", "isCorrect": true}, {"id": "aa707419-8316-493f-979d-9c5fbf4cbb6f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c3dbe6d4-2e36-4a2e-9cf2-2eafccc4dc71", "text": "Hány osztója van a 12-nek? (1, 2, 3, 4, 6, 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "127c13be-f5a7-4be5-8666-a954a05c8096", "text": "Melyik szám a 15 többszöröse az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "6fb6490c-2023-41f2-bef4-8be4fd6e727f", "text": "45", "isCorrect": true}, {"id": "70fa555d-23a8-4aa0-9fe5-ad226d58da01", "text": "5", "isCorrect": false}, {"id": "80c39d5d-7dec-4e14-ab5c-bb85ccff2744", "text": "3", "isCorrect": false}, {"id": "2f01bd04-979f-4685-9bd1-13e192ce6553", "text": "10", "isCorrect": false}], "timeLimit": 15}, {"id": "2f401462-57a5-4429-bf3f-adc4f91f0413", "text": "Minden számnak végtelen sok többszöröse van.", "type": "true-false", "options": [{"id": "43c8e349-1d06-4fd2-b3d6-68c7dc09ab08", "text": "Igaz", "isCorrect": true}, {"id": "03ce730f-8165-465b-854b-e87354f418a5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4d5f08f2-2b66-4795-88ba-9ed91494659a", "text": "Mi a 20 legkisebb pozitív osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "88475f43-f32f-4262-ad96-ef3d9032b495", "text": "Mi a 20 legnagyobb osztója önmagán kívül?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d7169fb0-a4ea-4631-81cc-dab1587d8a4d', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$14. óra: Számolás maradékokkal$q$, $q$Az osztási maradék fogalma, paritás vizsgálata, összeg maradéka.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "75a78aec-11f7-4c46-ac90-e4cebd99f807", "text": "Mennyi a maradék, ha 23-at elosztjuk 5-tel? (23 = 4*5 + 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "6be1e95f-5e78-4808-9ac2-4b16cfadf40e", "text": "Egy számot 4-gyel elosztva a lehetséges maradékok: 0, 1, 2, 3.", "type": "true-false", "options": [{"id": "58c4f4d6-9b10-4f9e-bf89-aa17bc5958de", "text": "Igaz", "isCorrect": true}, {"id": "6dcf0648-7944-45b2-a5c8-9db7c60f3ef5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ee056610-bd96-43fc-928f-dbf9edc55d84", "text": "Milyen maradékot ad 2-vel osztva minden páratlan szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "4e34b4bf-4e11-40b9-a367-b56180ecdd03", "text": "Két páratlan szám összege mindig páros szám.", "type": "true-false", "options": [{"id": "21e48294-23d3-4c12-9c32-16fc36274c49", "text": "Igaz (páratlan + páratlan = páros)", "isCorrect": true}, {"id": "8f09e004-3c85-4d41-87ee-47123eb9bda1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5cff4c6c-20e4-42db-bb08-e4ed2fbb74d0", "text": "Mennyi a maradék 37 : 10 esetén?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "cd370ab7-a95f-4f67-84c6-2135637fa19b", "text": "Két páros szám szorzata mindig páros szám.", "type": "true-false", "options": [{"id": "a9a2d497-3568-49c0-b173-134d901918b7", "text": "Igaz", "isCorrect": true}, {"id": "d6128ce9-8956-485a-a99b-2bb37b0e6df6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "856a7d18-8996-4047-a053-6358a9b838da", "text": "Melyik szám ad 0 maradékot 3-mal osztva?", "type": "multiple-choice", "options": [{"id": "4815dd40-e1f6-4107-9274-5805980a2a65", "text": "15", "isCorrect": true}, {"id": "57b37d30-9737-48e6-bd06-17b73dacfc10", "text": "16", "isCorrect": false}, {"id": "e9a81334-9425-45dd-8bfe-5010bb624398", "text": "17", "isCorrect": false}, {"id": "cd5bcb68-47dd-496f-b93f-5ec9dd0d6225", "text": "19", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('543858e8-c967-4a60-9c88-560fe771aa4a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$15. óra: Hány osztója van?$q$, $q$Természetes számok csoportosítása osztóik száma alapján, prímek és összetett számok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "48cd7a65-bc87-48e1-b1d2-19258faec1d0", "text": "Hogyan nevezzük azokat a számokat, amelyeknek pontosan 2 osztójuk van (1 és önmaga)?", "type": "multiple-choice", "options": [{"id": "59729795-7454-4809-b442-9ba336aa4c55", "text": "Prímszámok (prímek)", "isCorrect": true}, {"id": "4b818d7e-a9e5-4b8b-9430-19d57334afd1", "text": "Összetett számok", "isCorrect": false}, {"id": "60f19a6e-a7c1-4ac9-8da2-a00ab3b62738", "text": "Páros számok", "isCorrect": false}, {"id": "bd1923dc-59ea-4e61-b6c4-5b14c71eccaa", "text": "Negatív számok", "isCorrect": false}], "timeLimit": 15}, {"id": "ed7abf9e-e128-458a-ac6b-6453aafc32e8", "text": "Az 1 prímszám.", "type": "true-false", "options": [{"id": "91ced016-044a-4523-8f8a-0b61429c4b5c", "text": "Igaz", "isCorrect": false}, {"id": "7e2f0f6f-41d4-49e7-a3f8-96c761efe7df", "text": "Hamis (az 1 sem nem prím, sem nem összetett)", "isCorrect": true}], "timeLimit": 15}, {"id": "28443da1-db43-4242-a226-6785ff8a8ed2", "text": "Melyik a legkisebb prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "faee8164-be2d-4935-9184-c9b933a0cbdd", "text": "Melyik az egyetlen páros prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "e384e8ca-a681-4c8a-9734-dc5c02f79fad", "text": "Azokat a számokat, amelyeknek 2-nél több osztójuk van, összetett számoknak nevezzük.", "type": "true-false", "options": [{"id": "a09021e6-f314-4b61-9004-8ddb5aaa3b49", "text": "Igaz", "isCorrect": true}, {"id": "8d35c15a-015b-448f-95c0-3a8a553c753a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9c424340-e6e0-4927-b06b-345fc15d398a", "text": "Hány osztója van a 7-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "7b27dcdc-eccb-433e-9e25-68536f7af6ae", "text": "Melyik prím az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "a034d516-eb3c-4539-86f0-526cb32e67b1", "text": "13", "isCorrect": true}, {"id": "79f11f97-d45f-4bea-b37a-565d75581264", "text": "9", "isCorrect": false}, {"id": "ed95793d-82b3-4a22-b4b8-755d243d2b25", "text": "15", "isCorrect": false}, {"id": "75f97af4-6dc0-46fe-8923-3097b97c6776", "text": "21", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('dea45fba-f47b-4358-b3a8-6d210b71912d', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$16. óra: Feladatok az osztók számának meghatározására, számolás maradékokkal$q$, $q$Szöveges feladatok az osztókról és maradékokról.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "e7cd6094-2ab7-417f-bc2d-549eea3ad55e", "text": "Hány osztója van a 9-nek? (1, 3, 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "78a3fb6c-5e43-475a-b1e1-b3dc0ca6d504", "text": "A négyzetszámoknak páratlan számú osztójuk van.", "type": "true-false", "options": [{"id": "f528a5b5-434f-4670-a1e1-bddf9bbc6438", "text": "Igaz (pl. 9-nek 3 osztója van: 1, 3, 9)", "isCorrect": true}, {"id": "438e5c41-c30d-4785-9e04-4cc5de08f193", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b2f4575c-8be1-4e08-8fdd-89b36b977994", "text": "Ha 25 alma van és 4 gyerek között egyenlően elosztjuk, hány alma marad a kosárban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "551d50c4-3dba-4e73-a026-97d09100bd96", "text": "Hány prímszám van 10 és 20 között? (11, 13, 17, 19)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "51cdd9f4-f9e2-4cfc-9900-e3d5ff47d805", "text": "Melyik szám összetett szám az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "8e6dfc4e-ad0e-40ed-887c-aa6ccd716c50", "text": "27 (osztói: 1,3,9,27)", "isCorrect": true}, {"id": "8ee83abf-7e35-4d0b-b3a0-3213c9439ece", "text": "23", "isCorrect": false}, {"id": "37fb10ce-5c99-4cef-9710-88c6317a9ac0", "text": "29", "isCorrect": false}, {"id": "485691a0-5365-4ed9-b7a5-37ee885c1ca2", "text": "31", "isCorrect": false}], "timeLimit": 15}, {"id": "b187c0fc-2f4f-4940-9553-817c068b69ff", "text": "Minden páratlan szám prímszám.", "type": "true-false", "options": [{"id": "3077c365-186b-4d12-9162-864e6fce07e8", "text": "Igaz", "isCorrect": false}, {"id": "ca9a98e0-5ebe-460d-b851-7299695e000b", "text": "Hamis (pl. 9, 15, 21 nem prím)", "isCorrect": true}], "timeLimit": 15}, {"id": "4b3ac0e7-c40d-4808-a7ba-633001f1d7b7", "text": "Mennyi a legkisebb kétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2cc04846-72f3-486e-9d2e-841d6005bb92', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$17. óra: Oszthatóság 2-vel, 5-tel, 10-zel$q$, $q$Oszthatósági szabályok az utolsó számjegy alapján.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "f2c42ddb-8b9e-420a-9579-003495343b69", "text": "Mikor osztható egy szám 2-vel?", "type": "multiple-choice", "options": [{"id": "7479427d-dfbd-4d6b-bcdd-4253d1458b5e", "text": "Ha az utolsó számjegye páros (0, 2, 4, 6, 8)", "isCorrect": true}, {"id": "ee4c51fe-a270-4323-8714-cbac244ff48c", "text": "Ha a számjegyek összege 2", "isCorrect": false}, {"id": "17daee74-ac7c-4094-b474-46ffd26a6c68", "text": "Ha 5-re végződik", "isCorrect": false}, {"id": "808e2c23-6ec3-447f-a414-68f261cd56e9", "text": "Minden szám osztható 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "a58553e7-5a88-4167-8755-46ff15570ae9", "text": "Mikor osztható egy szám 5-tel?", "type": "multiple-choice", "options": [{"id": "08f7a01b-bb35-4f8d-8304-33183950ace4", "text": "Ha az utolsó számjegye 0 vagy 5", "isCorrect": true}, {"id": "298d32f3-80a7-4172-98d3-c2a6f7a7a6b1", "text": "Ha 2-re végződik", "isCorrect": false}, {"id": "02e9ec61-b525-4b02-96ce-9b8657388209", "text": "Ha páratlan", "isCorrect": false}, {"id": "ec244769-8a44-4a53-8fc3-71860153ef73", "text": "Ha a számjegyek összege 5", "isCorrect": false}], "timeLimit": 15}, {"id": "fe89c9b8-7d8a-4ac5-9ad5-c4558c1ad457", "text": "Mikor osztható egy szám 10-zel?", "type": "multiple-choice", "options": [{"id": "2baa4bef-f52b-4224-a7bf-349011a805a5", "text": "Ha az utolsó számjegye 0", "isCorrect": true}, {"id": "c36b1481-1b36-4524-b15e-26be7bac8c76", "text": "Ha az utolsó számjegye 5", "isCorrect": false}, {"id": "42ed9466-67c0-4d14-8f7b-3bffb276a393", "text": "Ha páros", "isCorrect": false}, {"id": "6f1903d1-7b99-47df-a67e-2979976fda7a", "text": "H