INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7b579a9e-caad-43ac-92c1-e2ca06e22d68', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$18. óra: Oszthatóság 3-mal és 9-cel$q$, $q$A számjegyek összegén alapuló oszthatósági szabályok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "6adcdc1f-17c3-4ca7-b1ad-2f0359b4eae2", "text": "Mikor osztható egy szám 3-mal?", "type": "multiple-choice", "options": [{"id": "28f0c47b-31e0-439d-8e73-9a133aa7fd73", "text": "Ha a számjegyeinek összege osztható 3-mal", "isCorrect": true}, {"id": "092d5e45-839b-4c4d-8809-6d505d4b2cf8", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "b9dc1eb1-f7a2-4c01-9377-b807b42e8968", "text": "Ha páratlan", "isCorrect": false}, {"id": "1401e437-ed29-4429-ba1c-7bec6a229fc4", "text": "Ha az utolsó számjegye 3, 6 vagy 9", "isCorrect": false}], "timeLimit": 15}, {"id": "8a09f85f-be93-46b0-a6a2-75ef94383e8a", "text": "Mikor osztható egy szám 9-cel?", "type": "multiple-choice", "options": [{"id": "568ea03b-c9f4-4ef3-abe9-e6805d1e7f9d", "text": "Ha a számjegyeinek összege osztható 9-cel", "isCorrect": true}, {"id": "6468e0e1-df95-44f5-81da-110152e769b8", "text": "Ha 9-re végződik", "isCorrect": false}, {"id": "e20cc958-0f79-4473-b89e-0ee351487be6", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "f690870c-2c58-4a70-aeeb-2d9bfc531528", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "cb2f774e-faad-4d86-9f3d-ada021290bb3", "text": "Mennyi a 243 számjegyeinek összege (2+4+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "6ab51673-09eb-4cba-85ee-e5c41e68ceb2", "text": "A 243 osztható 3-mal és 9-cel is.", "type": "true-false", "options": [{"id": "be71ff4a-cace-4851-acd3-5bb83a9f4304", "text": "Igaz", "isCorrect": true}, {"id": "71299d78-bc79-48a5-b67b-ef9c0b82e245", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"i