INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('23435aa7-4de8-46e5-87e2-803ceb9f30ca', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$19. óra: Oszthatóság 4-gyel és 100-zal$q$, $q$Oszthatósági szabály az utolsó két számjegy alapján.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "c2e7af54-9841-4773-887d-739715caa1cd", "text": "Mikor osztható egy szám 4-gyel?", "type": "multiple-choice", "options": [{"id": "9cd424c8-07d4-4fb3-860d-a0b3392621c5", "text": "Ha az utolsó két számjegyéből képzett kétjegyű szám osztható 4-gyel (vagy 00)", "isCorrect": true}, {"id": "918793a3-21a7-492f-8494-919c92488276", "text": "Ha 4-re végződik", "isCorrect": false}, {"id": "01f3de50-2a69-4182-a5d4-5a05c0b99ed7", "text": "Ha a számjegyek összege 4", "isCorrect": false}, {"id": "18595792-c23d-4677-aef5-b5c793fc6ab6", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "f94cd0bb-5d77-4ad8-8cd6-ce228af82bc0", "text": "Mikor osztható egy szám 100-zal?", "type": "multiple-choice", "options": [{"id": "f36ffed7-39aa-454d-b2b4-23185d0ca711", "text": "Ha az utolsó két számjegye 00", "isCorrect": true}, {"id": "f1ffde32-c066-423a-a184-6d94f82e4810", "text": "Ha 100-ra végződik", "isCorrect": false}, {"id": "0c83d78e-9139-4bd8-93de-be5971104457", "text": "Ha 0-ra végződik", "isCorrect": false}, {"id": "47241596-a129-4bd3-b830-3583d4735b48", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "45b9d966-feaf-42ba-8a56-3bb41a157261", "text": "A 316 osztható 4-gyel (mert 16 osztható 4-gyel).", "type": "true-false", "options": [{"id": "9a91a63e-4753-46f7-9ebe-3d6a61592d05", "text": "Igaz", "isCorrect": true}, {"id": "d01530d7-ce8a-4484-af3d-6338afd470ff", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7ce89eb3-14bf-4ef0-bcc7-65e79b7932ee", "text": "A 7500 osztható 100-zal és 4-gyel is.", "type": "true-false", "options": [{"id": "2b8653a0-9